def solve():
    n = 21
    # states: 0: (0,0), 1: (1,0), 2: (0,1)

    def count_independent_sets(initial_state):
        dp = [[0] * 3 for _ in range(n + 1)]
        if initial_state == 0:
            dp[1][0] = 1
        elif initial_state == 1:
            dp[1][1] = 1
        elif initial_state == 2:
            dp[1][2] = 1

        for j in range(2, n + 1):
            dp[j][0] = dp[j-1][0] + dp[j-1][1] + dp[j-1][2]
            dp[j][1] = dp[j-1][0] + dp[j-1][2]
            dp[j][2] = dp[j-1][0] + dp[j-1][1]

        if initial_state == 0 or initial_state == 1:
            return dp[n][0] + dp[n][1]
        elif initial_state == 2:
            return dp[n][0]
        else:
            return 0

    total = count_independent_sets(0) + count_independent_sets(1) + count_independent_sets(2)
    print(total)

solve()
